let inMiniProgramEnv = false;
let apiUrl = "/api/getContentByNid";

(function() {
    
    
    // 创建样式1
    const css = "#backBtn,#makeBtn{display:none;position:fixed;bottom:10vh;width:30vw;padding:1.3vh 6vw;background:#2196f3;color:#fff;border:none;cursor:pointer;z-index:9999;font-size:2.2vh;box-shadow:0 .4vh .8vh rgba(0,0,0,.1)}#backBtn{left:0;border-radius:0 5vw 5vw 0}#makeBtn{display:none; right:0;border-radius:5vw 0 0 5vw}";
    const style = document.createElement("style");
    style.textContent = css;
    document.head.appendChild(style);

    // 创建按钮
    const backBtn = Object.assign(document.createElement("button"), {
        id: "backBtn",
        className: "miniprogram-only",
        textContent: "返回",
    });
    
    const makeBtn = Object.assign(document.createElement("button"), {
        id: "makeBtn",
        className: "miniprogram-only",
        textContent: "制作",
    });
    
    document.body.append(backBtn, makeBtn);

    // 检测是否在微信小程序中
    function checkMiniProgramEnv() {
        return new Promise((resolve) =>{
            if (typeof wx === "undefined" || !wx.miniProgram) return resolve(false);
            wx.miniProgram.getEnv((res) =>resolve(res.miniprogram));
        });
    }
    
    if (window.location.search.includes('is_demo')) {
        apiUrl = apiUrl.replace("ByNid", "ByNid2");
    }
    
    /*
    ` / pages / make / index ? id = $ {
                window.dataInfo ? .id || ""
            }`,
            */
    // 显示按钮逻辑
    checkMiniProgramEnv().then((isMini) =>{
        if (!isMini) return;
        
        inMiniProgramEnv = true;
        
        if (!window.location.search.includes('?share')) {
            const music = document.getElementById('music');
            backBtn.style.display = "block";
            if (!window.location.search.includes('is_demo')) {
                makeBtn.style.display = "block";
            }
            
            backBtn.onclick = () => wx.miniProgram.navigateBack();
            makeBtn.onclick = () => {
                if(dataInfo.templateId == 61 || dataInfo.templateId == 63){
                    /*
                    alert("复制代码成功~");
                    */
                }else{
                    if(music){music.pause();}
                
                    wx.miniProgram.navigateTo({
                        url: '/pages/make/index?typeId='+ (dataInfo?.typeId || 1) +'&id=' + (dataInfo?.id || '')
                    });
                }
                
            };
        }
        
    });
    

})();

/**
 * 去除文本中所有中文（汉字+中文标点）
 * @param {string} text - 待处理文本
 * @returns {string} 去除中文后的文本
 */
function removeChinese(text) {
  // 正则匹配：中文汉字(\u4e00-\u9fa5) + 中文标点(\u3000-\u303f\uff00-\uffef)
  return decodeURI(text).replace(/[\u4e00-\u9fa5\u3000-\u303f\uff00-\uffef]/g, '');
}


