// 检测是否在微信环境（含 iPadOS）
function isMobileWeChat() {
    const ua = (navigator.userAgent || "").toLowerCase();
    if (!/micromessenger/.test(ua)) return false;        // 非微信
    if (/wechatdevtools/.test(ua)) return false;         // 排除微信开发者工具（桌面）
    const isMobileUA = /mobi|android|iphone|ipod|ipad|ios|windows phone/.test(ua);
    const isIPadOS = /macintosh/.test(ua) && typeof navigator.maxTouchPoints === 'number' && navigator.maxTouchPoints > 1;
    return isMobileUA || isIPadOS;                       // 安卓/iOS（含 iPadOS）
}

