// 发送前等待 iframeReady 后发送最新的views
function sendViewsToIframe(views) {
    if (iframeReady && window.frames.length > 0) {
        window.frames[0].postMessage(
            { type: "updateViews", views },
            "*"
        );
    } else {
        // 如果 iframe 还没加载好，循环等待
        setTimeout(() => sendViewsToIframe(views), 100);
    }
}

(async function loadData() {
    try {
        const res = await fetch(apiUrl + `?nid=${nid}` + '&host=' + window.location.hostname);
        const json = await res.json();
        if (!json.data) throw new Error("Empty data");
        dataInfo = json.data;
        if (dataInfo['404']){
            const getTarget = () => window.location.pathname.slice(1) + window.location.search;
            return (location.href = "/404.html?" + getTarget());
        }
        if (dataInfo['302']) return (location.href = dataInfo['302']);
        setDataInfo(dataInfo);
        localStorage.setItem('templateDate', JSON.stringify(dataInfo));
        
        //后台执行 addView 展现最新views（不阻塞页面）
        fetch(`/api/addView?nid=${nid}`)
            .then(res => res.json())
            .then(res => {
                if (res.code === 200 && typeof res.views === 'number') {
        
                    // 更新 dataInfo 和 localStorage
                    dataInfo.views = res.views;
                    localStorage.setItem('templateDate', JSON.stringify(dataInfo));
        
                    // 异步安全推送给 iframe
                    sendViewsToIframe(res.views);
                }
            })
            .catch(err => {
                console.warn("addView 上报失败：", err);
            });
        
        
    } catch (err) {
        const getTarget = () => window.location.pathname.slice(1) + window.location.search;
        location.href = "/404.html?" + getTarget();
        console.error("加载文案失败：", err);
    }
})();


(function() {
    // 获取 audio 元素
    const music = document.getElementById("music");

    // 定义播放函数
    function play() {
        if (!music) return;
        music.play();
        // 播放后移除触摸事件监听，避免多次触发
        document.removeEventListener("touchstart", play, false);
    }

    // 定义入口函数（可导出）
    function playMusic() {
        if (!music) return;
        // 立即尝试播放1
        music.play();

        // 三种事件保障兼容自动播放（含微信）
        document.addEventListener("DOMContentLoaded", play, false);
        document.addEventListener("WeixinJSBridgeReady", play, false);
        document.addEventListener("touchstart", play, false);
    }
    
    // 如果你希望在外部调用：
    window.playMusic = playMusic;
})();

