function getMMDDHHmm() {
  const date = new Date(); // 获取当前时间
  const hour = String(date.getHours()).padStart(2, '0'); // 小时（00-23），补零
  const month = String(date.getMonth() + 1).padStart(2, '0'); // 月份（01-12），补零
  const day = String(date.getDate()).padStart(2, '0'); // 日期（01-31），补零
  const minute = String(date.getMinutes()).padStart(2, '0'); // 分钟（00-59）
  
  // 拼接格式：小时 + 月份 + 日期 → HHMMDD（6位字符串）
  return month + day + hour + minute;
}
    
