musicBtn.onclick = () => {
    music.paused ? music.play().catch(()=>{}) : music.pause();
    player?.toggle();
    document.querySelector("#musicBtn img")?.classList.toggle("roll");
};


//监听iframe消息


window.addEventListener('message', function (e) {
    //显示右下角按钮组
    if (e.data && e.data.source === 'pages' && e.data.type === 'showBtn') {
        mp();
        autoWord();
        setTimeout(function() {
            autoShowBtn(1);
        }, 2000);
    }
    
    if (e.data && e.data.source === 'pages' && e.data.type === 'mpBack') {
        console.log("mpBack");
        mp();
    }
    
    if (e.data && e.data.source === 'pages' && e.data.type === 'autoWord') {
        console.log("autoWord");
        autoWord();
    }
    console.log("message", e.data);
});
